    def __init__(self, secret_key):
        self.secret_key = secret_key

    def verify_signature(self, payload, signature_header):
        expected_signature = self._calculate_signature(payload)
        return hmac.compare_digest(expected_signature, signature_header)

    def _calculate_signature(self, payload):
        return hashlib.sha256(self.secret_key.encode() + payload).hexdigest()

